assignments.value:
={{
  $('Normalize RMA Data').item.json.requestType === 'Warranty Claim'
  ||
  $now.startOf('day') <= DateTime.fromISO($('Read Order from Sheets').item.json.purchaseDate)
    .plus({ days: Number($('Set Configuration Parameters').item.json.standardReturnWindowDays) })
    .endOf('day')
}}

values.content:
=Product: {{ $('Read Product Record from Sheets').item.json.productName }}
Product Category: {{ $('Read Product Record from Sheets').item.json.category }}
Request Type: {{ $('Normalize RMA Data').item.json.requestType }}
Requested Resolution: {{ $('Normalize RMA Data').item.json.requestedResolution }}

Customer Issue:
{{ $('Normalize RMA Data').item.json.issueDescription }}

parameters.message:
=RMA claim requires manual approval.

{{ $json.approvalSummary }}

Please review the case and approve or reject this request.

assignments.value:
={{
  Number($('Read Order from Sheets').item.json.productPrice) > 0
  &&
  Number($('Read Order from Sheets').item.json.productPrice)
  <= Number($('Assess Claim Value').item.json.claimValue)
}}

parameters.sendTo:
={{ $('When RMA Request Submitted').item.json.formMode === 'test'
? $('Set Configuration Parameters').item.json.testCustomerEmail
: $('Read Current RMA Status').item.json.customerEmail }}
